# Referee's check for question E: can "bad on Z_n' for some e | n'" be the level-0 event of ONE system of
# values (Theorem T' as stated)?  A level-0 event of one system (group V, values v_i) is the set of sign
# vectors in the kernel K of Z^m -> V, x -> sum x_i v_i, and every subgroup K of Z^m is such a kernel.
# So the set A of bad signings of a multiset on an odd Z_n' is such an event iff no sign vector outside A
# lies in the subgroup of Z^m generated by A.  Exact integers.  Imports nothing of the author's.
# usage: onev.py m n [n ...]   (n odd; every multiset containing 0)
import sys, itertools
import numpy as np
from cyc import divisors, xpow_mod

def echelon(rows, m):
    rows = [list(r) for r in rows if any(r)]
    basis = []
    def lead(r):
        for i, a in enumerate(r):
            if a:
                return i
    for col in range(m):
        cand = [r for r in rows if lead(r) == col]
        rows = [r for r in rows if lead(r) != col]
        while len(cand) > 1:
            cand.sort(key=lambda r: abs(r[col]))
            piv, new = cand[0], [cand[0]]
            for r in cand[1:]:
                q = r[col] // piv[col]
                r2 = [a - q * b for a, b in zip(r, piv)]
                if r2[col]:
                    new.append(r2)
                elif any(r2):
                    rows.append(r2)
            cand = new
        if cand:
            basis.append((col, cand[0]))
    return basis

def member(x, basis):
    x = list(x)
    for col, b in basis:
        if x[col] % b[col]:
            return False
        q = x[col] // b[col]
        x = [a - q * c for a, c in zip(x, b)]
    return not any(x)

# self-test with the three-element example of the report: values (1,1,0) and (0,1,1) in Z
sg3 = [tuple(-1 if (s >> i) & 1 else 1 for i in range(3)) for s in range(8)]
A3 = [x for x in sg3 if x[0] + x[1] == 0 or x[1] + x[2] == 0]
bas = echelon(A3, 3)
extra = [x for x in sg3 if x not in A3 and member(x, bas)]
print("example: positions any, values (1,1,0) and (0,1,1): signings bad at level 0 for some e:", len(A3),
      "; sign vectors outside it in the subgroup it generates:", extra)

m = int(sys.argv[1])
for n in map(int, sys.argv[2:]):
    dn = divisors(n)
    rows = [np.array(xpow_mod(d, n), dtype=np.int64).reshape(n, -1) for d in dn]
    T = np.concatenate(rows, axis=1)
    starts = np.cumsum([0] + [r.shape[1] for r in rows])[:-1]
    S = 1 << m
    sgl = [tuple(-1 if (s >> i) & 1 else 1 for i in range(m)) for s in range(S)]
    sg = np.array(sgl, dtype=np.int64)
    cnt = notone = 0
    ex = None
    for c in itertools.combinations_with_replacement(range(n), m - 1):
        B = [0] + list(c)
        Z = np.add.reduceat(((sg @ T[B]) != 0).astype(np.int32), starts, axis=1) == 0
        bad = Z.any(axis=1)
        cnt += 1
        A = [sgl[s] for s in range(S) if bad[s]]
        if not A:
            continue
        bas = echelon(A, m)
        out = [sgl[s] for s in range(S) if not bad[s] and member(sgl[s], bas)]
        if out:
            notone += 1
            if ex is None:
                ex = (tuple(B), len(A), out[0])
    print(f"m={m} n={n}: multisets {cnt}; the set of bad signings is NOT the level-0 event of any one system of values "
          f"in {notone}; first: {ex}", flush=True)
